        Specimen(id="ichthyosaurus",name="Ichthyosaurus communis",rockClass=RockClass.FOSSIL,category="Marine Reptile",tagline="Dolphin-like marine reptile with enormous eyes.",emoji="🐬",colorHex=0xFF5090B0,description="Ichthyosaurus was a dolphin-shaped marine reptile with huge eyes adapted for deep-sea hunting. It gave birth to live young — fossilized mothers with embryos have been found.",formation="Blue Lias and Posidonia Shale, Jurassic marine deposits of England and Germany.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark gray","Black shale"),whereFound=listOf("Lyme Regis, Dorset, UK","Holzmaden, Germany"),funFacts=listOf("Gave birth to live young — fossil mothers with embryos found.","Eyes were the size of dinner plates.","Mary Anning discovered the first complete skeleton."),uses="Museum displays, research.",rarity="Uncommon",geologicalPeriod="Early Jurassic",age="~200–190 mya"),
        Specimen(id="leedsichthys",name="Leedsichthys problematicus",rockClass=RockClass.FOSSIL,category="Prehistoric Fish",tagline="The largest fish ever — 50-ft filter-feeding giant.",emoji="🐟",colorHex=0xFF5090A0,description="Leedsichthys was the largest bony fish in history — a 50-ft filter feeder like a giant Jurassic whale shark. It swam through the same seas as Liopleurodon, filtering plankton with its enormous gill rakers.",formation="Oxford Clay, Middle Jurassic of England.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark gray","Brown"),whereFound=listOf("Oxford Clay, Peterborough, England","France","Germany","Chile"),funFacts=listOf("Largest bony fish ever — 50 ft, filter-fed like a whale.","Same Jurassic seas as Liopleurodon and plesiosaurs.","Difficult to reconstruct because the skeleton was delicate."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Middle Jurassic",age="~165 mya"),
        Specimen(id="liopleurodon",name="Liopleurodon ferox",rockClass=RockClass.FOSSIL,category="Marine Reptile",tagline="Massive-jawed apex predator of the Jurassic seas.",emoji="🐊",colorHex=0xFF306090,description="Liopleurodon was a short-necked pliosaur with massive jaws and teeth up to 4 inches long. It was an apex predator of Jurassic seas, hunting fish, squid, and other marine reptiles.",formation="Oxford Clay, Middle Jurassic of England and France.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark gray","Black"),whereFound=listOf("Oxford Clay, England","France"),funFacts=listOf("Apex predator of Jurassic seas.","Teeth up to 4 inches long.","Popularized by Walking with Dinosaurs — though exaggerated in size."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Middle Jurassic",age="~166–160 mya"),
        Specimen(id="megalania",name="Megalania (Varanus priscus)",rockClass=RockClass.FOSSIL,category="Prehistoric Mammal",tagline="The 20-ft giant monitor lizard — the largest land lizard ever.",emoji="🦎",colorHex=0xFF5A4030,description="Megalania was a giant monitor lizard — the largest terrestrial lizard known — reaching up to 20 ft long. It was the apex predator of Pleistocene Australia alongside the marsupial lion. Related to modern Komodo dragons.",formation="Pleistocene cave and river deposits across Australia.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark brown","Red-brown"),whereFound=listOf("Queensland, Australia","New South Wales, Australia","South Australia"),funFacts=listOf("Largest land lizard ever — twice the size of a Komodo dragon.","Likely venomous like its modern Komodo dragon relatives.","Coexisted with early Aboriginal Australians."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Pleistocene",age="~2.5 million–50,000 years"),
        Specimen(id="megalodon",name="Megalodon (Otodus megalodon)",rockClass=RockClass.FOSSIL,category="Prehistoric Fish",tagline="The 60-ft mega-shark — largest predatory fish in history.",emoji="🦈",colorHex=0xFF6090B0,description="Megalodon was the largest shark and largest predatory fish ever — reaching 60 ft, three times the size of a great white. Its teeth alone reached 7 inches. It preyed on whales worldwide for 20 million years.",formation="Fossil teeth found in Miocene-Pliocene marine deposits worldwide. Skeleton was cartilage so mostly only teeth survive.",hardness="—",luster="— (fossil tooth)",streak="—",crystalSystem="—",chemicalFormula="Ca₅(PO₄)₃OH (enameloid)",commonColors=listOf("Black","Gray","Brown","Tan"),whereFound=listOf("North Carolina, USA (beach finds)","Peru","Chile","Japan","Florida, USA"),funFacts=listOf("Teeth up to 7 inches — the size of a human hand.","Three times larger than a great white shark.","Probably went extinct due to cooling oceans and prey loss."),uses="Collector specimens, museum displays, paleoichthyology research.",rarity="Uncommon (teeth)",geologicalPeriod="Miocene–Pliocene",age="~23–3.6 mya"),
        Specimen(id="meganeura",name="Meganeura monyi",rockClass=RockClass.FOSSIL,category="Prehistoric Insect",tagline="Eagle-sized dragonfly with 28-inch wingspan from the Carboniferous.",emoji="🦟",colorHex=0xFF70A0C9,description="Meganeura was a giant griffinfly — an ancestor of dragonflies — with a 28-inch wingspan. It flew through Carboniferous forests when oxygen levels were 35% (vs 21% today), allowing insects to grow enormous.",formation="Carboniferous coal measures in Commentry, France.",hardness="—",luster="— (fossil)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Carbon film",commonColors=listOf("Dark gray","Black","Coal matrix"),whereFound=listOf("Commentry, France","England"),funFacts=listOf("28-inch wingspan — like an eagle.","High oxygen levels (35%) allowed giant insects.","The largest flying insect ever known."),uses="Museum displays, paleoentomology research.",rarity="Rare",geologicalPeriod="Carboniferous",age="~305 mya"),
        Specimen(id="oviraptor",name="Oviraptor philoceratops",rockClass=RockClass.FOSSIL,category="Dinosaur",tagline="The misnamed 'egg thief' that was actually protecting its own nest.",emoji="🥚",colorHex=0xFF5A7050,description="Oviraptor was wrongly accused of stealing eggs when discovered near a nest — it was actually brooding its own eggs like a modern bird. Had a toothless beak and distinctive crest.",formation="Djadochta Formation, Late Cretaceous of Mongolia.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Red-brown","Gray"),whereFound=listOf("Djadochta Fm, Gobi Desert, Mongolia"),funFacts=listOf("Fossil found on a nest — wrongly called 'egg thief.'","Actually died protecting its own eggs.","Toothless beak and crested skull."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Late Cretaceous",age="~75 mya"),
        Specimen(id="paraceratherium",name="Paraceratherium transouralicum",rockClass=RockClass.FOSSIL,category="Prehistoric Mammal",tagline="The largest land mammal ever — 18 ft tall, 20 tons.",emoji="🦏",colorHex=0xFF908070,description="Paraceratherium was the largest land mammal in Earth's history — a hornless rhinoceros relative that stood 18 ft at the shoulder and weighed 20 tons. It browsed treetops like a mammalian sauropod across Oligocene Asia.",formation="Oligocene terrestrial deposits across central Asia.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Light brown","Gray","Tan"),whereFound=listOf("Mongolia","Kazakhstan","Pakistan","China"),funFacts=listOf("Larger than any elephant — the largest land mammal ever.","Had no horn — a giant hornless rhino relative.","Browsed treetops like a giraffe but 3x taller."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Oligocene",age="~34–23 mya"),
        Specimen(id="phorusrhacos",name="Phorusrhacos longissimus (Terror Bird)",rockClass=RockClass.FOSSIL,category="Prehistoric Bird",tagline="True terror bird — 8-ft apex predator of prehistoric South America.",emoji="🦅",colorHex=0xFFB06050,description="Phorusrhacos was a true apex predator — an 8-ft flightless bird that dominated South America for millions of years after the dinosaurs. It had a hooked beak and could run down prey at high speed on the Pampas grasslands.",formation="Miocene Santa Cruz Formation, Argentina.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Light brown","Gray"),whereFound=listOf("Santa Cruz Fm, Patagonia, Argentina"),funFacts=listOf("True apex predator of Miocene South America.","Could run down prey at high speed.","Related to the seriemas — still living in South America today."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Miocene",age="~20–13 mya"),
        Specimen(id="plesiosaurus",name="Plesiosaurus dolichodeirus",rockClass=RockClass.FOSSIL,category="Marine Reptile",tagline="Long-necked marine reptile that inspired the Loch Ness Monster.",emoji="🦕",colorHex=0xFF4080A0,description="Plesiosaurus had a small head on a long snake-like neck, a barrel-shaped body, and four paddle-like flippers. It 'flew' through Jurassic seas like underwater flight.",formation="Blue Lias, Early Jurassic of England. First discovered by Mary Anning in 1823.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark gray","Limestone"),whereFound=listOf("Lyme Regis, Dorset, UK"),funFacts=listOf("The Loch Ness Monster is often imagined as a plesiosaur.","Swam using all four flippers in a 'flying' motion.","Mary Anning discovered the first complete specimen."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Early Jurassic",age="~200–190 mya"),
        Specimen(id="pteranodon-longiceps",name="Pteranodon longiceps",rockClass=RockClass.FOSSIL,category="Pterosaur",tagline="Toothless flying reptile with 23-ft wingspan.",emoji="🦉",colorHex=0xFF6FBF8A,description="Pteranodon had a 23-ft wingspan with a toothless beak for scooping fish from the Western Interior Seaway. Over 1,200 specimens found. Males had large backward-pointing crests. Rarity: Common (Niobrara Chalk).",formation="Niobrara Chalk, Late Cretaceous. Over 1,200 specimens — the best-known pterosaur.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Light gray","Tan","Cream"),whereFound=listOf("Niobrara Chalk, Kansas, USA","Smoky Hill Chalk, USA"),funFacts=listOf("Pteranodon is NOT a dinosaur.","Males had large crests; females had small ones.","Could fly across the Western Interior Seaway in a day."),uses="Museum displays, research.",rarity="Common (Niobrara Chalk)",geologicalPeriod="Late Cretaceous",age="~86–84 mya"),
        Specimen(id="pulmonoscorpius",name="Pulmonoscorpius kirktonensis",rockClass=RockClass.FOSSIL,category="Prehistoric Insect",tagline="Giant 28-inch scorpion from the Carboniferous.",emoji="🦂",colorHex=0xFF507090,description="Pulmonoscorpius was a giant scorpion reaching 28 inches — larger than a house cat. It had a large stinger and pincers for hunting in Carboniferous coal swamps. Its lungs gave it an advantage over gill-breathing arthropods.",formation="East Kirkton Limestone, Carboniferous of Scotland.",hardness="—",luster="— (fossil)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Chitin (fossilized)",commonColors=listOf("Dark gray","Black"),whereFound=listOf("East Kirkton, West Lothian, Scotland"),funFacts=listOf("Larger than a house cat at 28 inches.","Had book lungs — could breathe air.","One of the largest scorpions ever."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Carboniferous",age="~335 mya"),
        Specimen(id="quetzalcoatlus",name="Quetzalcoatlus northropi",rockClass=RockClass.FOSSIL,category="Pterosaur",tagline="Largest flying creature ever — 36-ft wingspan, tall as a giraffe.",emoji="🦅",colorHex=0xFF5FA070,description="The largest flying animal ever discovered, with a 36-ft wingspan — as wide as a small plane. Stood as tall as a giraffe on the ground and likely hunted like a giant stork.",formation="Javelina Formation, Late Cretaceous of Texas. Named after the Aztec feathered serpent god.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Light brown","Gray"),whereFound=listOf("Javelina Fm, Big Bend, Texas, USA"),funFacts=listOf("Wingspan was 36 ft — like a small airplane.","Stood as tall as a giraffe on the ground.","Named after the Aztec god Quetzalcoatl."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Late Cretaceous",age="~68–66 mya"),
        Specimen(id="radiolaria",name="Radiolaria",rockClass=RockClass.FOSSIL,category="Single-Celled Organism",tagline="Intricate glass skeletons — microscopic crystal snowflakes of the sea.",emoji="❄️",colorHex=0xFFC0B0D0,description="Radiolarians are single-celled plankton with intricate silica skeletons shaped like delicate geometric snowflakes, stars, and spheres. Their glassy shells form radiolarian ooze on the deep ocean floor, preserving as chert. Rarity: Abundant (microscopic).",formation="Marine sediments worldwide. Silica skeletons accumulate as radiolarian ooze and lithify into chert.",hardness="—",luster="— (microscopic silica)",streak="—",crystalSystem="—",chemicalFormula="SiO₂ (siliceous)",commonColors=listOf("Transparent","White","Pale blue"),whereFound=listOf("Deep ocean sediments worldwide","Barbados","California, USA"),funFacts=listOf("Skeletons look like microscopic glass snowflakes.","Some are shaped like perfect spheres with radiating spines.","Their silica shells become chert and flint."),uses="Biostratigraphy, chert identification, oceanographic research.",rarity="Abundant (microscopic)",geologicalPeriod="Cambrian–Present",age="~540 mya–Present"),
        Specimen(id="sigillaria",name="Sigillaria",rockClass=RockClass.FOSSIL,category="Prehistoric Flora",tagline="The ribbed tree — another coal-forming giant of the Carboniferous.",emoji="🌲",colorHex=0xFF60A060,description="Sigillaria was a relative of Lepidodendron with a similar scale-tree form but with vertical ribs instead of diamond scars. It also grew in Carboniferous coal swamps, reaching 100 ft. Rarity: Common (fossil).",formation="Carboniferous coal measures worldwide.",hardness="—",luster="— (fossil)",streak="—",crystalSystem="— (fossilized plant)",chemicalFormula="Carbonized plant matter",commonColors=listOf("Dark gray","Black"),whereFound=listOf("Pennsylvania, USA","Wales, UK","Nova Scotia, Canada"),funFacts=listOf("Trunk had vertical ribs instead of diamond patterns.","Coal-forming tree alongside Lepidodendron.","Name means 'seal-mark' — for the leaf scar patterns."),uses="Coal, fossil collectors.",rarity="Common (fossil)",geologicalPeriod="Carboniferous",age="~359–299 mya"),
        Specimen(id="smilodon",name="Smilodon fatalis (Saber-toothed Cat)",rockClass=RockClass.FOSSIL,category="Prehistoric Mammal",tagline="7-inch saber teeth on a muscular ambush predator.",emoji="🐯",colorHex=0xFFC97050,description="Smilodon was the iconic saber-toothed cat with 7-inch canine teeth used for a precise killing bite to the throat. Thousands of specimens from La Brea Tar Pits make it one of the best-known Ice Age predators.",formation="Pleistocene tar seeps and sediment deposits. La Brea Tar Pits has produced over 2,000 individuals.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark brown","Amber","Gray"),whereFound=listOf("La Brea Tar Pits, Los Angeles, USA","Florida, USA","South America"),funFacts=listOf("Used its saber teeth for a precise throat bite — not to crush bone.","California's state fossil.","Despite the name, NOT closely related to modern tigers."),uses="Museum displays, paleontology research.",rarity="Uncommon (La Brea)",geologicalPeriod="Pleistocene",age="~2.5 million–10,000 years"),
        Specimen(id="spinosaurus",name="Spinosaurus aegyptiacus",rockClass=RockClass.FOSSIL,category="Dinosaur",tagline="Largest carnivorous dinosaur — 50-ft semiaquatic hunter.",emoji="🐊",colorHex=0xFF609050,description="Spinosaurus reached 50 ft with a massive sail, crocodile-like skull, and dense bones adapted for swimming. The largest known carnivorous dinosaur hunted giant fish in Cretaceous rivers.",formation="Bahariya Formation and Kem Kem Beds — mid-Cretaceous river systems. Original holotype destroyed in WWII Munich bombing.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Reddish-brown","Gray","Tan"),whereFound=listOf("Bahariya Fm, Egypt","Kem Kem Beds, Morocco"),funFacts=listOf("Sail may have been for display, thermoregulation, or as a fin.","Had a paddle-like tail for swimming.","Longest carnivorous dinosaur — longer than T. rex."),uses="Museum displays, scientific research.",rarity="Extremely Rare",geologicalPeriod="Mid-Cretaceous",age="~99–93 mya"),
        Specimen(id="therizinosaurus",name="Therizinosaurus cheloniformis",rockClass=RockClass.FOSSIL,category="Dinosaur",tagline="Three-foot claws on a pot-bellied theropod plant-eater.",emoji="🦕",colorHex=0xFF6A7040,description="One of the most bizarre dinosaurs — a 33-ft theropod that evolved herbivory with a pot belly, long neck, beaked mouth, and enormous 3-ft claws.",formation="Nemegt Formation, Late Cretaceous of Mongolia.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark brown","Gray","Tan"),whereFound=listOf("Nemegt Fm, Gobi Desert, Mongolia"),funFacts=listOf("Claws originally thought to belong to a giant turtle.","A theropod that evolved to eat plants.","Claws likely used to pull branches."),uses="Museum displays, research.",rarity="Rare",geologicalPeriod="Late Cretaceous",age="~70 mya"),
        Specimen(id="thylacine",name="Thylacine (Thylacinus cynocephalus)",rockClass=RockClass.FOSSIL,category="Prehistoric Mammal",tagline="The Tasmanian tiger — modern marsupial predator gone extinct in 1936.",emoji="🐺",colorHex=0xFF8B7A60,description="The thylacine was the largest carnivorous marsupial of modern times, resembling a dog with tiger-like stripes. It was hunted to extinction in Tasmania, with the last one dying in captivity in 1936. Fossil evidence shows it once lived throughout Australia and New Guinea.",formation="Pleistocene and Holocene cave deposits in Australia. The thylacine survived into the 20th century.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Brown","Gray","Tan"),whereFound=listOf("Tasmania, Australia","Mainland Australia (fossil)","New Guinea (fossil)"),funFacts=listOf("The last one died in Hobart Zoo in 1936 — now a symbol of extinction.","Males had a pouch too — a unique marsupial trait.","Some people still search for surviving thylacines in Tasmania."),uses="Museum displays, conservation research.",rarity="Extinct (1936)",geologicalPeriod="Pleistocene–Holocene",age="~2 million–1936 AD"),
        Specimen(id="triceratops-horridus",name="Triceratops horridus",rockClass=RockClass.FOSSIL,category="Dinosaur",tagline="Three-horned tank with a massive frill.",emoji="🦏",colorHex=0xFF9BBF7A,description="Triceratops reached 30 ft long with a 6-ft skull bearing three horns and a bony frill. The brow horns exceeded 3 ft in adults for defense and combat.",formation="Hell Creek and Lance Formations — one of the last non-avian dinosaurs.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark brown","Gray","Tan"),whereFound=listOf("Hell Creek Fm, USA","Lance Fm, Wyoming","Scollard Fm, Alberta"),funFacts=listOf("Frill likely used for display and species recognition.","Hundreds of teeth in a constantly-replaced 'dental battery.'","Wyoming's state dinosaur."),uses="Museum displays, scientific research.",rarity="Uncommon",geologicalPeriod="Late Cretaceous",age="~68–66 mya"),
        Specimen(id="tyrannosaurus-rex",name="Tyrannosaurus rex",rockClass=RockClass.FOSSIL,category="Dinosaur",tagline="40-foot apex predator with 12,800 psi bite force.",emoji="🦖",colorHex=0xFF8BBF6A,description="Tyrannosaurus rex was one of the largest land predators ever, reaching 40 feet long with a 5-foot skull of serrated teeth. Its bite could crush bone. Despite its bulk, it could run 25 mph.",formation="Hell Creek Formation — Late Cretaceous river floodplain deposits across western North America. Over 50 partial skeletons discovered.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark brown","Gray","Tan matrix"),whereFound=listOf("Hell Creek Fm, Montana/South Dakota, USA","Lance Fm, Wyoming, USA","Alberta, Canada"),funFacts=listOf("Strongest bite of any land animal — 12,800 psi.","Tiny 3-ft arms could each lift 400 lbs.","Lived ~28 years based on bone growth rings."),uses="Museum displays, scientific research.",rarity="Rare",geologicalPeriod="Late Cretaceous",age="~68–66 mya"),
        Specimen(id="velociraptor-mongoliensis",name="Velociraptor mongoliensis",rockClass=RockClass.FOSSIL,category="Dinosaur",tagline="Turkey-sized feathered predator with a lethal sickle claw.",emoji="🦅",colorHex=0xFF6A9050,description="Velociraptor was about the size of a turkey, covered in feathers, with a 2.5-inch retractable sickle claw on each foot. Quill knobs on arm bones prove it had feathers.",formation="Djadochta Formation, Gobi Desert — Late Cretaceous desert deposits.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Light brown","Gray","Tan"),whereFound=listOf("Djadochta Fm, Gobi Desert, Mongolia","Bayan Mandahu, Inner Mongolia"),funFacts=listOf("Famous 'fighting dinosaurs' fossil shows it locked in combat with Protoceratops.","Much smaller than movie version — only ~33 lbs.","Its sickle claw stabbed vital areas of prey."),uses="Museum displays, scientific research.",rarity="Rare",geologicalPeriod="Late Cretaceous",age="~75–71 mya"),
        Specimen(id="woolly-mammoth",name="Woolly Mammoth (Mammuthus primigenius)",rockClass=RockClass.FOSSIL,category="Prehistoric Mammal",tagline="Ice Age giant with 15-ft curved tusks and shaggy coat.",emoji="🐘",colorHex=0xFFC9A87C,description="The woolly mammoth roamed the northern hemisphere during the Pleistocene. Covered in thick fur with a fat hump for energy storage, it had curved tusks up to 15 ft long. Frozen carcasses in Siberian permafrost provide DNA and soft tissue. Rarity: Uncommon (fossil).",formation="Pleistocene permafrost and sediment deposits across the northern hemisphere.",hardness="—",luster="— (fossil bone/ivory)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark brown","Cream ivory","Gray"),whereFound=listOf("Siberia, Russia (permafrost)","Wrangel Island (last survivors)","La Brea Tar Pits, California","Great Plains, USA"),funFacts=listOf("Frozen mammoths with hair, skin, and stomach contents have been found.","The last mammoths lived on Wrangel Island just 4,000 years ago.","Mammoth ivory is still found in Siberia today."),uses="Museum displays, ivory artifacts, scientific research.",rarity="Uncommon (fossil)",geologicalPeriod="Pleistocene",age="~400,000–4,000 years ago"),
        Specimen(id="woolly-rhino",name="Woolly Rhinoceros (Coelodonta antiquitatis)",rockClass=RockClass.FOSSIL,category="Prehistoric Mammal",tagline="Ice Age tank with a massive front horn and shaggy fur.",emoji="🦏",colorHex=0xFFA08060,description="The woolly rhino was a heavily-built Ice Age rhinoceros with thick fur, a fatty hump, and a massive flattened front horn used to sweep away snow while grazing. Cave paintings show it with a dark band around its midsection.",formation="Pleistocene permafrost and sediment deposits across Eurasia.",hardness="—",luster="— (fossil bone)",streak="—",crystalSystem="— (fossilized)",chemicalFormula="Ca₅(PO₄)₃OH",commonColors=listOf("Dark brown","Gray","Cream"),whereFound=listOf("Siberia, Russia","Ukraine","England","France"),funFacts=listOf("Cave paintings show it had a dark band around its body.","Its horn was made of keratin — not bone — but fossilizes in permafrost.","Coexisted with early humans who hunted it."),uses="Museum displays, research.",rarity="Uncommon",geologicalPeriod="Pleistocene",age="~350,000–10,000 years"),
